function updateZoomControls(){const zoom=canvas.getZoom();$('#zoom-value').textContent=`${Math.round(zoom*50)}%`;$('#zoom-out').disabled=zoom<=.2;$('#zoom-in').disabled=zoom>=8;$('#zoom-fit').setAttribute('aria-pressed',zoomMode==='fit');}
