function dragBox(x1,y1,x2,y2,type,shift){const side=x1>=pageWidth()?1:0;x2=clamp(x2,side*pageWidth(),side*pageWidth()+pageWidth());y2=clamp(y2,0,pageHeight());let x=Math.min(x1,x2),y=Math.min(y1,y2),w=Math.abs(x2-x1),h=Math.abs(y2-y1);if(type==='line'){if(Math.abs(x2-x1)>=Math.abs(y2-y1)){x=Math.min(x1,x2);y=y1-.5;w=Math.abs(x2-x1);h=1;}else{x=x1-.5;y=Math.min(y1,y2);w=1;h=Math.abs(y2-y1);}}else if(type==='svg'&&pendingSvg&&!shift){const aspect=pendingSvg.aspect||1;if(w<h*aspect)w=h*aspect;else h=w/aspect;x=x2<x1?x1-w:x1;y=y2<y1?y1-h:y1;}else if(shift){const size=Math.max(w,h);w=h=size;x=x2<x1?x1-size:x1;y=y2<y1?y1-size:y1;}x-=side*pageWidth();x=clamp(x,0,pageWidth());y=clamp(y,0,pageHeight());w=clamp(w,0,pageWidth()-x);h=clamp(h,0,pageHeight()-y);return {x,y,w,h};}
